#[allow(unsafe_op_in_unsafe_fn)]
pub unsafe fn csv_parse(
    p: &mut CsvParser<'_>,
    s: &[u8],
    cb1: Option<unsafe extern "C" fn(*mut core::ffi::c_void, usize, *mut core::ffi::c_void)>,
    cb2: Option<unsafe extern "C" fn(i32, *mut core::ffi::c_void)>,
    data: *mut core::ffi::c_void,
) -> usize {
    macro_rules! save_state {
        () => {
            {
                p.quoted = quoted;
                p.pstate = pstate;
                p.spaces = spaces;
                p.entry_pos = entry_pos;
            }
        };
    }

    macro_rules! put_byte {
        ($index:expr, $byte:expr) => {
            p.entry_buf
                .as_deref_mut()
                .expect("CSV entry buffer is not allocated")[$index] = $byte;
        };
    }

    macro_rules! emit_field {
        ($index:expr, $quoted_value:expr) => {
            {
                if p.options & 8 != 0 {
                    put_byte!($index, 0);
                }
                if let Some(callback) = cb1 {
                    let entry_ptr = if p.options & 16 != 0
                        && $quoted_value == 0
                        && $index == 0
                    {
                        core::ptr::null_mut()
                    } else {
                        p.entry_buf
                            .as_deref_mut()
                            .expect("CSV entry buffer is not allocated")
                            .as_mut_ptr()
                            .cast::<core::ffi::c_void>()
                    };
                    callback(entry_ptr, $index, data);
                }
            }
        };
    }

    macro_rules! is_space_char {
        ($byte:expr) => {{
            let byte = $byte;
            match is_space {
                Some(predicate) => predicate(byte) != 0,
                None => byte == 0x20 || byte == 0x09,
            }
        }};
    }

    macro_rules! is_term_char {
        ($byte:expr) => {{
            let byte = $byte;
            match is_term {
                Some(predicate) => predicate(byte) != 0,
                None => byte == 0x0d || byte == 0x0a,
            }
        }};
    }

    let delim = p.delim_char;
    let quote = p.quote_char;
    let is_space = p.is_space;
    let is_term = p.is_term;
    let mut quoted = p.quoted;
    let mut pstate = p.pstate;
    let mut spaces = p.spaces;
    let mut entry_pos = p.entry_pos;
    let mut pos = 0;

    if p.entry_buf.is_none() && pos < s.len() && csv_increase_buffer(Some(&mut *p)) != 0 {
        save_state!();
        return pos;
    }

    while pos < s.len() {
        let entry_limit = if p.options & 8 != 0 {
            p.entry_size.wrapping_sub(1)
        } else {
            p.entry_size
        };

        if entry_pos == entry_limit && csv_increase_buffer(Some(&mut *p)) != 0 {
            save_state!();
            return pos;
        }

        let c = s[pos];
        pos += 1;

        match pstate {
            0 | 1 => {
                let space = is_space_char!(c);
                let term = is_term_char!(c);

                if space && c != delim {
                    continue;
                } else if term {
                    if pstate == 1 {
                        if quoted == 0 {
                            entry_pos = entry_pos.wrapping_sub(spaces);
                        }
                        emit_field!(entry_pos, quoted);
                        pstate = 1;
                        entry_pos = 0;
                        quoted = 0;
                        spaces = 0;
                        if let Some(callback) = cb2 {
                            callback(c as i32, data);
                        }
                        pstate = 0;
                        entry_pos = 0;
                        quoted = 0;
                        spaces = 0;
                    } else if p.options & 2 != 0 {
                        if let Some(callback) = cb2 {
                            callback(c as i32, data);
                        }
                        pstate = 0;
                        entry_pos = 0;
                        quoted = 0;
                        spaces = 0;
                    }
                    continue;
                } else if c == delim {
                    if quoted == 0 {
                        entry_pos = entry_pos.wrapping_sub(spaces);
                    }
                    emit_field!(entry_pos, quoted);
                    pstate = 1;
                    entry_pos = 0;
                    quoted = 0;
                    spaces = 0;
                } else if c == quote {
                    pstate = 2;
                    quoted = 1;
                } else {
                    pstate = 2;
                    quoted = 0;
                    put_byte!(entry_pos, c);
                    entry_pos += 1;
                }
            }
            2 => {
                if c == quote {
                    if quoted != 0 {
                        put_byte!(entry_pos, c);
                        entry_pos += 1;
                        pstate = 3;
                    } else {
                        if p.options & 1 != 0 {
                            p.status = 1;
                            save_state!();
                            return pos.wrapping_sub(1);
                        }
                        put_byte!(entry_pos, c);
                        entry_pos += 1;
                        spaces = 0;
                    }
                } else if c == delim {
                    if quoted != 0 {
                        put_byte!(entry_pos, c);
                        entry_pos += 1;
                    } else {
                        entry_pos = entry_pos.wrapping_sub(spaces);
                        emit_field!(entry_pos, quoted);
                        pstate = 1;
                        entry_pos = 0;
                        quoted = 0;
                        spaces = 0;
                    }
                } else {
                    let term = is_term_char!(c);
                    let space = is_space_char!(c);

                    if term {
                        if quoted == 0 {
                            entry_pos = entry_pos.wrapping_sub(spaces);
                            emit_field!(entry_pos, quoted);
                            pstate = 1;
                            entry_pos = 0;
                            quoted = 0;
                            spaces = 0;
                            if let Some(callback) = cb2 {
                                callback(c as i32, data);
                            }
                            pstate = 0;
                            entry_pos = 0;
                            quoted = 0;
                            spaces = 0;
                        } else {
                            put_byte!(entry_pos, c);
                            entry_pos += 1;
                        }
                    } else if quoted == 0 && space {
                        put_byte!(entry_pos, c);
                        entry_pos += 1;
                        spaces += 1;
                    } else {
                        put_byte!(entry_pos, c);
                        entry_pos += 1;
                        spaces = 0;
                    }
                }
            }
            3 => {
                let term = is_term_char!(c);

                if c == delim {
                    entry_pos = entry_pos.wrapping_sub(spaces).wrapping_sub(1);
                    emit_field!(entry_pos, quoted);
                    pstate = 1;
                    entry_pos = 0;
                    quoted = 0;
                    spaces = 0;
                } else if term {
                    entry_pos = entry_pos.wrapping_sub(spaces).wrapping_sub(1);
                    emit_field!(entry_pos, quoted);
                    pstate = 1;
                    entry_pos = 0;
                    quoted = 0;
                    spaces = 0;
                    if let Some(callback) = cb2 {
                        callback(c as i32, data);
                    }
                    pstate = 0;
                    entry_pos = 0;
                    quoted = 0;
                    spaces = 0;
                } else if is_space_char!(c) {
                    put_byte!(entry_pos, c);
                    entry_pos += 1;
                    spaces += 1;
                } else if c == quote {
                    if spaces != 0 {
                        if p.options & 1 != 0 {
                            p.status = 1;
                            save_state!();
                            return pos.wrapping_sub(1);
                        }
                        spaces = 0;
                        put_byte!(entry_pos, c);
                        entry_pos += 1;
                    } else {
                        pstate = 2;
                    }
                } else {
                    if p.options & 1 != 0 {
                        p.status = 1;
                        save_state!();
                        return pos.wrapping_sub(1);
                    }
                    pstate = 2;
                    spaces = 0;
                    put_byte!(entry_pos, c);
                    entry_pos += 1;
                }
            }
            _ => {}
        }
    }

    save_state!();
    pos
}

